diff --git a/src/ui/glyph_cache.c b/src/ui/glyph_cache.c
index 7865ef4..da4fc36 100644
--- a/src/ui/glyph_cache.c
+++ b/src/ui/glyph_cache.c
@@ -14,6 +14,7 @@
 #define GLYPH_PADDING 1

 #define ZWJ 0x200d
+#define VS15 0xfe0e
 #define VS16 0xfe0f
 #define KEYCAP 0x20e3

@@ -500,6 +505,25 @@ uint32_t vd_utf8_next(const char *text, int *length)
     return codepoint;
 }

+// Emoji_Presentation below U+1F000, from Unicode's emoji-data.txt: these draw as emoji without U+FE0F.
+static const uint32_t EMOJI_PRESENTATION[][2] = {
+    {0x231a, 0x231b}, {0x23e9, 0x23ec}, {0x23f0, 0x23f0}, {0x23f3, 0x23f3}, {0x25fd, 0x25fe}, {0x2614, 0x2615},
+    {0x2648, 0x2653}, {0x267f, 0x267f}, {0x2693, 0x2693}, {0x26a1, 0x26a1}, {0x26aa, 0x26ab}, {0x26bd, 0x26be},
+    {0x26c4, 0x26c5}, {0x26ce, 0x26ce}, {0x26d4, 0x26d4}, {0x26ea, 0x26ea}, {0x26f2, 0x26f3}, {0x26f5, 0x26f5},
+    {0x26fa, 0x26fa}, {0x26fd, 0x26fd}, {0x2705, 0x2705}, {0x270a, 0x270b}, {0x2728, 0x2728}, {0x274c, 0x274c},
+    {0x274e, 0x274e}, {0x2753, 0x2755}, {0x2757, 0x2757}, {0x2795, 0x2797}, {0x27b0, 0x27b0}, {0x27bf, 0x27bf},
+    {0x2b1b, 0x2b1c}, {0x2b50, 0x2b50}, {0x2b55, 0x2b55},
+};
+
+static bool emoji_by_default(uint32_t codepoint)
+{
+    if (codepoint >= 0x1f000) return true;
+    for (size_t i = 0; i < sizeof(EMOJI_PRESENTATION) / sizeof(EMOJI_PRESENTATION[0]); i++) {
+        if (in_range(codepoint, EMOJI_PRESENTATION[i][0], EMOJI_PRESENTATION[i][1])) return true;
+    }
+    return false;
+}
+
 static bool is_regional_indicator(uint32_t codepoint)
 {
     return codepoint >= 0x1f1e6 && codepoint <= 0x1f1ff;
@@ -523,7 +547,7 @@ int vd_emoji_cluster(const char *text, VdEmojiSequence *sequence)
     uint32_t first = vd_utf8_next(text, &bytes);
     int next_length = 0;
     uint32_t next = text[bytes] != '\0' ? vd_utf8_next(text + bytes, &next_length) : 0;
-    if (first < 0x1f000 && next != VS16 && next != KEYCAP) return 0;
+    if (next == VS15 || (!emoji_by_default(first) && next != VS16 && next != KEYCAP)) return 0;

     memset(sequence, 0, sizeof(*sequence));
     append(sequence, first);

diff --git a/src/ui/glyph_cache.h b/src/ui/glyph_cache.h
index 28f126e..94a7251 100644
--- a/src/ui/glyph_cache.h
+++ b/src/ui/glyph_cache.h
@@ -99,8 +99,9 @@ VdGlyphCacheStats glyph_cache_stats(void);
 // Malformed UTF-8 decodes one byte at a time as VD_UTF8_REPLACEMENT.
 uint32_t vd_utf8_next(const char *text, int *length);
 // The bytes of the emoji cluster at text, with its codepoints in sequence, or 0 when text does not start one. A
-// cluster starts at a codepoint from U+1F000 up or one followed by U+FE0F or a keycap mark, and takes skin tones,
-// tags, a second regional indicator and ZWJ-joined codepoints.
+// cluster starts at a codepoint from U+1F000 up, an emoji-style symbol like U+2728, or one followed by U+FE0F or a
+// keycap mark; U+FE0E after it keeps it text. It takes skin tones, tags, a second regional indicator and ZWJ-joined
+// codepoints.
 int vd_emoji_cluster(const char *text, VdEmojiSequence *sequence);

 #endif /* GLYPH_CACHE_H */

diff --git a/tests/glyph_cache_harness.c b/tests/glyph_cache_harness.c
index f960509..a5c90a4 100644
--- a/tests/glyph_cache_harness.c
+++ b/tests/glyph_cache_harness.c
@@ -357,9 +358,12 @@ static void test_emoji_clusters(void)
                    (const uint32_t[]){0x1f468, 0x200d, 0x1f469, 0x200d, 0x1f467}, 5, "a ZWJ sequence is one cluster");
     expect_cluster("\xf0\x9f\x91\xa8\xe2\x80\x8d", 4, (const uint32_t[]){0x1f468}, 1,
                    "a trailing ZWJ is not part of the cluster");
+    expect_cluster("\xe2\x9c\xa8!", 3, (const uint32_t[]){0x2728}, 1, "an emoji-style symbol needs no U+FE0F");
+    expect_cluster("\xe2\x9c\xa8\xef\xb8\x8e", 0, NULL, 0, "U+FE0E keeps an emoji-style symbol text");
+    expect_cluster("\xe2\x86\x92", 0, NULL, 0, "an arrow is not an emoji");
 }

-// Pretends assets/emoji holds 1f3ae, 2764 and 1f468: 8x8 images, opaque red inside a transparent border.
+// Pretends assets/emoji holds 1f3ae, 2764, 2728 and 1f468: 8x8 images, opaque red inside a transparent border.
 static int emoji_loads = 0;
 static int emoji_last_length = 0;

@@ -413,6 +418,8 @@ static void test_emoji(const VdGlyphFont *font)

     VdEmojiSequence heart = cluster_of("\xe2\x9d\xa4\xef\xb8\x8f");
     expect(glyph_cache_get_emoji(font, size, &heart).color, "a symbol with U+FE0F resolves to its emoji image");
+    VdEmojiSequence sparkles = cluster_of("\xe2\x9c\xa8");
+    expect(glyph_cache_get_emoji(font, size, &sparkles).color, "an emoji-style symbol resolves to its emoji image");

     VdEmojiSequence family = cluster_of("\xf0\x9f\x91\xa8\xe2\x80\x8d\xf0\x9f\x91\xa9\xe2\x80\x8d\xf0\x9f\x91\xa7");
     VdEmojiSequence man = cluster_of("\xf0\x9f\x91\xa8");
